import {normalizeMyWorlds,myWorldAction,beginMyWorldTravel,tickMyWorldTravel,myWorldCapture,myWorldRestore} from '../src/my-world.js';
import test from 'node:test';import assert from 'node:assert/strict';
import {normalizeRooms,ensureRoom,roomAction,roomView,roomItemArt,roomThemes,roomSpots} from '../src/habitat.js';import {normalizeTrailMachines,trailMachineAction} from '../src/trail-machines.js';import {normalizeMachines} from '../src/machines.js';import {normalizeExpeditions,expeditionEnter} from '../src/expeditions.js';import {professors,zoneProfessor,professorView,professorPortrait} from '../src/professors.js';import {professorElon} from '../src/construction.js';import {professorMike} from '../src/hq-tech.js';import {pipToolLessons} from '../src/pip.js';
const setup=()=>{const exp=normalizeExpeditions(),s=normalizeTrailMachines(),garage=normalizeMachines({models:[{id:'m1',type:'habitat',color:'blue'}]});expeditionEnter(exp,'forest');trailMachineAction(exp,s,garage,{type:'place',modelId:'m1',pad:0});ensureRoom(s,s.placements[0].id);return {exp,s,garage};};
test('a saved habitat room supports placement, moving, replacement, putting away and undo without dragging',()=>{const {s}=setup();const r=s.rooms[s.roomOpen];roomAction(s,{type:'choose',item:'desk'});roomAction(s,{type:'spot',slot:4});assert.equal(r.slots[4],'desk');roomAction(s,{type:'move',slot:4});assert.equal(r.slots[4],'desk');roomAction(s,{type:'spot',slot:1});assert.equal(r.slots[4],null);assert.equal(r.slots[1],'desk');roomAction(s,{type:'remove',slot:1});assert.equal(r.slots[1],null);roomAction(s,{type:'undo'});assert.equal(r.slots[1],'desk');assert.equal(r.history.length,2);});
test('room themes/layouts survive normalized save, moving and packing, with archived room access',()=>{const {s,exp,garage}=setup(),id=s.roomOpen;roomAction(s,{type:'theme',value:'space'});const before=JSON.stringify(s.rooms[id]);trailMachineAction(exp,s,garage,{type:'place',modelId:'m1',moveId:id,pad:1});assert.equal(JSON.stringify(s.rooms[id]),before);trailMachineAction(exp,s,garage,{type:'pack',id});const copy=normalizeTrailMachines(JSON.parse(JSON.stringify(s)));assert.equal(copy.rooms[id].theme,'space');assert.equal(ensureRoom(copy,id),true);roomAction(copy,{type:'exit'});assert.equal(copy.roomOpen,null);assert.equal(copy.rooms[id].theme,'space');});
test('displays require earned samples/plants/memories and do not spend discoveries',()=>{const {s}=setup(),ctx={minerals:[{id:'quartz',name:'Quartz'}],plants:[{id:'bean',name:'Bean'}],discoveries:[{id:'cave-water',name:'Water table'}]},before=JSON.stringify(ctx);roomAction(s,{type:'choose',item:'sample:iron'},ctx);assert.equal(s.roomChoice,null);for(const [slot,item]of ['sample:quartz','plant:bean','memory:cave-water'].entries()){roomAction(s,{type:'choose',item},ctx);roomAction(s,{type:'spot',slot},ctx);assert.equal(s.rooms[s.roomOpen].slots[slot],item);}assert.equal(JSON.stringify(ctx),before);});
test('bed rest, PIP dock and science desk stay optional and resumable',()=>{const {s}=setup();assert.equal(roomAction(s,{type:'use',slot:0}).pause,true);assert.equal(roomAction(s,{type:'resume'}).pause,false);assert.match(roomAction(s,{type:'use',slot:2}).message,/PIP is ready/);roomAction(s,{type:'choose',item:'desk'});roomAction(s,{type:'spot',slot:3});assert.equal(roomAction(s,{type:'use',slot:3}).effect,'journal');assert.equal(roomAction(s,{type:'exit'}).pause,false);});
test('safe room normalization bounds slots/history and every room menu fits native controls',()=>{const {s}=setup();assert.deepEqual(normalizeRooms({bad:{slots:['bed']}}),{});for(const route of ['furniture:0','furniture:1','colors','displays','samples:0','plants:0','memories:0','spot:0','look:0','help','library:0'])assert.ok(roomView(s,route,{}).actions.length<=6,route);assert.equal(roomSpots.length,6);for(const k of Object.keys(roomThemes))assert.ok(k);assert.match(roomItemArt('sample:quartz'),/<svg/);});
test('zone faculty covers all science environments while preserving Mike and Elon',()=>{assert.equal(professors.elon.name,professorElon.name);assert.equal(professors.mike.intro,professorMike.intro);assert.equal(Object.keys(professors).length,12);for(const [zone,id]of Object.entries({coding:'mike',robotics:'mike',engineering:'elon',rocketlab:'elon',farm:'leena',aquatic:'marina',forest:'rowan',dig:'petra',diglands:'petra',flight:'aya',magnetism:'farah',chapterMoon:'mei'}))assert.equal(zoneProfessor(zone),id);assert.equal(zoneProfessor('grounds',{active:'ocean'}),'marina');assert.equal(zoneProfessor('grounds',{active:'farm',colony:{kind:'planet'}}),'mei');});
test('each professor has repeatable real activity links, optional PIP help and an original placeholder portrait',()=>{for(const [id,p]of Object.entries(professors)){assert.ok(p.activity.system&&p.second.page);if(p.activity.system==='piptool')assert.ok(pipToolLessons[p.activity.page]);const v=professorView(id);assert.ok(v.text.includes('PIP'));assert.ok(v.actions.some(a=>a.type==='page'&&a.route==='help'));for(const route of ['home','help','directory:0','directory:1','directory:2','directory:3'])assert.ok(professorView(id,route).actions.length<=5);assert.match(professorPortrait(id),/<svg/);}assert.match(professors.nia.intro,/not assume life/);});

test('colony rooms remain independent across worlds, travel and profile reload',()=>{const h={myWorlds:normalizeMyWorlds(),expeditions:normalizeExpeditions(),trailMachines:normalizeTrailMachines()},garage=normalizeMachines({models:[{id:'m1',type:'habitat',color:'blue'}]});for(const id of ['home','moon'])myWorldAction(h,{type:'create',id});beginMyWorldTravel(h,'home');tickMyWorldTravel(h,0,{skip:true});trailMachineAction(h.expeditions,h.trailMachines,garage,{type:'place',modelId:'m1',pad:0});const id=h.trailMachines.placements[0].id;ensureRoom(h.trailMachines,id);roomAction(h.trailMachines,{type:'theme',value:'sunset'});beginMyWorldTravel(h,'moon');assert.equal(h.trailMachines.roomOpen,null);tickMyWorldTravel(h,0,{skip:true});assert.equal(Object.keys(h.trailMachines.rooms).length,0);beginMyWorldTravel(h,'home');tickMyWorldTravel(h,0,{skip:true});assert.equal(h.trailMachines.rooms[id].theme,'sunset');ensureRoom(h.trailMachines,id);myWorldCapture(h);const copy={...h,myWorlds:normalizeMyWorlds(JSON.parse(JSON.stringify(h.myWorlds)))};myWorldRestore(copy);assert.equal(copy.trailMachines.roomOpen,id);assert.equal(copy.trailMachines.rooms[id].theme,'sunset');});
